selector_to_html = {"a[href=\"#equation-dx2-sepd-2\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dx2-sepd-2\">\n\\[\\frac{\\partial^2}{\\partial x^2} f(x) - f(x)K=0 \\]</div>", "a[href=\"#equation-gen-form\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-gen-form\">\n\\[\\frac{\\partial^2}{\\partial x^2} y(x) - y(x) K = 0 \\]</div>", "a[href=\"#term-partial-differential-equation\"]": "<dt id=\"term-partial-differential-equation\">partial differential equation </dt><dd><p>An equation involving the partial derivatives of an unknown function. An expression for the function that satisfies the partial differential equation (PDE) is considered a solution to the PDE. There may be multiple solutions to a PDE, analogous to how the equation <span class=\"math notranslate nohighlight\">\\(9 = \\sqrt{x^2}\\)</span> has two solutions (<span class=\"math notranslate nohighlight\">\\(x = +3, -3\\)</span>)</p></dd>", "a[href=\"#equation-dx2-sep\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dx2-sep\">\n\\[\\frac{1}{f(x)} \\frac{\\partial^2}{\\partial x^2} f(x)= \\frac{1}{v^2 g(t)} \\frac{\\partial^2}{\\partial t^2} g(t)\\]</div>", "a[href=\"#equation-a-0-t\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-a-0-t\">\n\\[\\Psi(0,t) = 0 \\]</div>", "a[href=\"#equation-d2adx2\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-d2adx2\">\n\\[\\frac{\\partial ^2 \\Psi}{\\partial x ^2} = \\frac{1}{v^2} \\frac{\\partial ^2 \\Psi}{\\partial t^2}\\]</div>", "a[href=\"#the-2-d-classical-wave-equation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">4.2. </span>The 2-D Classical Wave Equation<a class=\"headerlink\" href=\"#the-2-d-classical-wave-equation\" title=\"Link to this heading\">#</a></h2><p>Following the same process as in <a class=\"reference internal\" href=\"#class-wave-1d\"><span class=\"std std-numref\">Section 4.1</span></a>, we can describe the motion of a wave on a 2-D rectangular membrane by solving the partial differential equation:</p>", "a[href=\"#term-angular-frequency\"]": "<dt id=\"term-angular-frequency\">angular frequency</dt><dd><p>rate of change in the value of an angle (angle per unit time)</p></dd>", "a[href=\"#equation-v\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-v\">\n\\[v = \\frac{dx}{dt}\\]</div>", "a[href=\"#term-boundary-conditions\"]": "<dt id=\"term-boundary-conditions\">boundary conditions</dt><dd><p>known values or relationships that apply the edges (boundaries) of asystem</p></dd>", "a[href=\"#equation-k-0-soln\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-k-0-soln\">\n\\[y(x) = C_1 e^{kx} + C_2 e^{-kx} \\]</div>", "a[href=\"#term-Euler-s-formula\"]": "<dt id=\"term-Euler-s-formula\">Euler\u2019s formula</dt><dd><p><span class=\"math notranslate nohighlight\">\\(e^{ix} = \\cos(x) + i \\sin(x)\\)</span></p></dd>", "a[href=\"#equation-soln-2\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-soln-2\">\n\\[g(t) = A_n \\cos (\\omega_n t + \\phi_n)\\]</div>", "a[href=\"#the-1-d-classical-wave-equation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">4.1. </span>The 1-D Classical Wave Equation<a class=\"headerlink\" href=\"#the-1-d-classical-wave-equation\" title=\"Link to this heading\">#</a></h2><p>Let us consider a model system: an oscillating string fixed at two points, <span class=\"math notranslate nohighlight\">\\(x=0\\)</span> and <span class=\"math notranslate nohighlight\">\\(x=l\\)</span>. Our objective is to determine a function that describes the motion of the string at any position and time: <span class=\"math notranslate nohighlight\">\\(\\Psi(x, t)\\)</span>.</p>", "a[href=\"#equation-a-l-t\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-a-l-t\">\n\\[\\Psi(l,t) = 0 \\]</div>", "a[href=\"#equation-1d-wave\"]": "<div class=\"highlighted-equation math notranslate nohighlight\" id=\"equation-1d-wave\">\n\\[\\Psi(x,t) = \\sum_{n=1}^{\\infty} A_n\\cos\\left(\\omega_n t+ \\phi_n \\right) \\cdot \\sin \\left( \\frac{n\\pi}{l} x \\right)\\]</div>", "a[href=\"#class-wave-1d\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">4.1. </span>The 1-D Classical Wave Equation<a class=\"headerlink\" href=\"#the-1-d-classical-wave-equation\" title=\"Link to this heading\">#</a></h2><p>Let us consider a model system: an oscillating string fixed at two points, <span class=\"math notranslate nohighlight\">\\(x=0\\)</span> and <span class=\"math notranslate nohighlight\">\\(x=l\\)</span>. Our objective is to determine a function that describes the motion of the string at any position and time: <span class=\"math notranslate nohighlight\">\\(\\Psi(x, t)\\)</span>.</p>", "a[href=\"#equation-prod\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-prod\">\n\\[\\Psi(x,t) = f(x) g(t)\\]</div>", "a[href=\"#equation-dx2fgdx2\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dx2fgdx2\">\n\\[\\frac{\\partial^2}{\\partial x^2} f(x)g(t)= \\frac{1}{v^2} \\frac{\\partial^2}{\\partial t^2} f(x)g(t)\\]</div>", "a[href=\"#equation-2d-wave-gen\"]": "<div class=\"highlighted-equation math notranslate nohighlight\" id=\"equation-2d-wave-gen\">\n\\[\\Psi(x,y,t) = \\sum_{n_x=1}^{\\infty}  \\sum_{n_y=1}^{\\infty} \\left[ A_{n_x,n_y} \\cos \\left(\\omega_{n_x, n_y} t + \\phi_{n_x, n_y} \\right) + B_{n_x,n_y} \\sin \\left( \\omega_{n_x,n_y} t+ \\phi_{n_x, n_y} \\right) \\right]  \\cdot \\sin \\left( \\frac{n_x \\pi}{l_x} x \\right) \\cdot \\sin \\left( \\frac{n_y \\pi}{l_y} y \\right)\\]</div>", "a[href=\"#equation-dt2-sepd-3\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dt2-sepd-3\">\n\\[\\frac{\\partial^2}{\\partial t^2} g(t) - \\beta^2 v^2 g(t) = 0 \\]</div>", "a[href=\"#equation-dx2-sepd\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dx2-sepd\">\n\\[\\frac{1}{f(x)} \\frac{\\partial^2}{\\partial x^2} f(x) = K \\]</div>", "a[href=\"#equation-dt2-sepd\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dt2-sepd\">\n\\[\\frac{1}{v^2 g(t)} \\frac{\\partial^2}{\\partial t^2} g(t) = K \\]</div>", "a[href=\"#renam\"]": "<aside class=\"footnote brackets\" id=\"renam\" role=\"doc-footnote\">\n<span class=\"label\"><span class=\"fn-bracket\">[</span>1<span class=\"fn-bracket\">]</span></span>\n<span class=\"backrefs\">(<a href=\"#id1\" role=\"doc-backlink\">1</a>,<a href=\"#id2\" role=\"doc-backlink\">2</a>)</span>\n<p>We simply renamed the constant <span class=\"math notranslate nohighlight\">\\(\\sqrt{K}\\)</span> to avoid having to write out square roots.</p>\n</aside>", "a[href=\"#equation-a-x-t\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-a-x-t\">\n\\[\\Psi(x,t) = A_n \\cos\\left(\\omega_n t + \\phi_n\\right) \\cdot \\sin \\left( \\frac{n\\pi}{l}x \\right)\\]</div>", "a[href=\"#equation-soln-1\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-soln-1\">\n\\[f(x) = B \\sin \\left(\\frac{n\\pi}{l} x\\right)\\]</div>", "a[href=\"#equation-beta\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-beta\">\n\\[\\beta = \\frac{n\\pi}{l}\\]</div>", "a[href=\"#equation-second-deriv\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-second-deriv\">\n\\[\\frac{\\partial ^2}{\\partial x ^2} \\Psi(x,t) = \\frac{\\partial}{\\partial x} \\frac{\\partial}{\\partial x} \\Psi(x,t)\\]</div>", "a[href=\"#equation-dt2-sepd-2\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dt2-sepd-2\">\n\\[\\frac{\\partial^2}{\\partial t^2} g(t) - v^2 g(t)K = 0 \\]</div>", "a[href=\"#wave-mechanics-energy-states\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">4. </span>Wave Mechanics &amp; Energy States<a class=\"headerlink\" href=\"#wave-mechanics-energy-states\" title=\"Link to this heading\">#</a></h1><p>For a statistical mechanics description of atomic and molecular energy states, we need a theory for describing the motion of atomic and molecular systems. One could use classical mechanics descriptions, essentially assuming that these macroscopic relationships will hold at the atomic and molecular scale. However, one could also take note that <a class=\"reference internal\" href=\"#term-particle-wave-duality\"><span class=\"xref std std-term\">particle-wave duality</span></a> posits that matter (particularly atomic-scale matter) exibits wavelike motion.</p><p>Notably, classical physics already has established theoretical models for the motion of waves (i.e., wave mechanics). If atomic-scale particules also behave as waves\u2013and if classical wave mechanics is \u201ctrue\u201d\u2013it should be possible to describe the motion of atomic-scale systems by applying classical wave mechanics.</p>", "a[href=\"#equation-2d-wave\"]": "<div class=\"highlighted-equation math notranslate nohighlight\" id=\"equation-2d-wave\">\n\\[\\Psi(x,y,t) = \\left[ A_{n_x,n_y} \\cos \\left(\\omega_{n_x, n_y} t + \\phi_{n_x, n_y} \\right) + B_{n_x,n_y} \\sin \\left( \\omega_{n_x,n_y} t+ \\phi_{n_x, n_y} \\right) \\right]  \\cdot \\sin \\left( \\frac{n_x \\pi}{l_x} x \\right) \\cdot \\sin \\left( \\frac{n_y \\pi}{l_y} y \\right)\\]</div>", "a[href=\"#term-particle-wave-duality\"]": "<dt id=\"term-particle-wave-duality\">particle-wave duality</dt><dd><p>Light and matter exhibit both particle-like and wave-like behaviors. The particle-like nature of light (electromagnetic radiation) was demonstrated through the photoelectric effect. Louis de Broglie theorized that it could then be true that particulate matter might also exhibit wave-like behaviors, and derived a prediction for the wavelength of a particle (<span class=\"math notranslate nohighlight\">\\(\\lambda = h/\\rho\\)</span>, where <span class=\"math notranslate nohighlight\">\\(\\lambda\\)</span> is the wavelength, <span class=\"math notranslate nohighlight\">\\(h\\)</span> is Planck\u2019s constant, and <span class=\"math notranslate nohighlight\">\\(\\rho\\)</span> is the particle momentum.) This prediction shows that the wavelike nature of matter is only relevant for very small particles, but this bears considerable implications for the motion of atomic-scale particulates such as electrons.</p></dd>", "a[href=\"#equation-k-0-soln1\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-k-0-soln1\">\n\\[y(x) = C_3 e^{ikx} + C_4 e^{-ikx}\\]</div>", "a[href=\"#equation-dt2-sepd-soln\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-dt2-sepd-soln\">\n\\[g(t) = D \\cos (\\beta v t) + E \\sin (\\beta v t)\\]</div>", "a[href=\"#glossary\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\"><span class=\"section-number\">4.3. </span>Glossary<a class=\"headerlink\" href=\"#glossary\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#equation-k-0-soln2\"]": "<div class=\"math notranslate nohighlight\" id=\"equation-k-0-soln2\">\n\\[y(x) = C_5 \\cos (kx) + C_6 \\sin(kx)\\]</div>", "a[href=\"#equation-2d-wave-final\"]": "<div class=\"highlighted-equation math notranslate nohighlight\" id=\"equation-2d-wave-final\">\n\\[\\Psi(x,y) =  \\sin \\left( \\frac{n_x \\pi}{l_x} x \\right) \\cdot \\sin \\left( \\frac{n_y \\pi}{l_y} y \\right)\\]</div>", "a[href=\"#equation-2d-wave-gen-final\"]": "<div class=\"highlighted-equation math notranslate nohighlight\" id=\"equation-2d-wave-gen-final\">\n\\[\\Psi(x,y) = \\sum_{n_x=1}^{\\infty}  \\sum_{n_y=1}^{\\infty} \\sin \\left( \\frac{n_x \\pi}{l_x} x \\right) \\cdot \\sin \\left( \\frac{n_y \\pi}{l_y} y \\right)\\]</div>"}
skip_classes = ["headerlink", "sd-stretched-link", "exercise", "solution"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'top', maxWidth: 500, interactive: true, theme: 'light-border',
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
